function cancelStaleDispatchedRuns(repoInfo, ciWorkflow, branch, currentSha) {
    if (!branch || !currentSha) return 0;
    try {
        var res = cli_execute_command({
            command: 'gh api "repos/' + repoInfo.owner + '/' +
