+// Scope: completed CANCELLED runs with head_sha === the CURRENT head,
+// EXCLUDING the SM's own dispatched validation lane (event
+// workflow_dispatch — validate_pr owns re-dispatching that, a rerun here
+// would race it). Newest cancelled run PER workflow path only: the
+// watchdogs are stateless, the newest run recomputes and re-stamps the
+// current state — re-running every burst corpse burns runners for the
+// same stamps.
+//
+// Convergence: a rerun flips the run to queued/in_progress, so the active
+// guard (any non-dispatch run in flight on this head) skips the next
+// ticks until the fresh stamps land and BLOCKED clears → merge-validated
+// consumes the arm. Fail-open per run (a 409 "already queued" or a
+// retired workflow must not cost the other heals); a probe failure throws
+// — the caller's try/catch turns it into a loud skip, next tick retries.
+// DRY probes but never POSTs (DRY means NO side effects).
+// Returns { active, runs, healed } — runs = healable runs found, healed =
+// rerun POSTs issued (0 in DRY).
+function rerunCancelledChecks(repoInfo, headSha, key) {
+    var res = cli_execute_command({
+        command: 'gh api "repos/' + repoInfo.owner + '/' + repoInfo.repo +
+                 '/actions/runs?head_sha=' + headSha + '&per_page=50"'
+    });
+    var parsed = mcpParse((res || {}).output || (res || {}).stdout || res);
