+    // Active guard (any non-dispatch run on this head): a rerun or a
+    // fresh event run is already healing the head — firing again
+    // mid-flight would only stack more cancellations.
+    var active = list.some(function (r) {
+        return r && r.head_sha === headSha && r.event !== 'workflow_dispatch' &&
+            ACTIVE_RUN_STATUSES.indexOf(r.status) !== -1;
+    });
+    if (active) {
+        console.log('  ⏭️  ' + key + ' cancelled-checks heal already in flight' +
+                    ' on this head — skip');
+        return { active: true, runs: 0, healed: 0 };
+    }
+    // Newest cancelled run per workflow path (REST lists newest-first,
+    // but the order is an implementation detail — compare explicitly).
+    var newest = {};
+    list.forEach(function (r) {
+        if (!r || r.head_sha !== headSha || r.event === 'workflow_dispatch') return;
+        if (r.status !== 'completed' || r.conclusion !== 'cancelled') return;
