+            newest[path] = r;
+        }
+    });
+    var runs = Object.keys(newest).map(function (p) { return newest[p]; });
+    if (!runs.length) {
+        console.log('  ⏭️  ' + key + ' no cancelled non-dispatch runs on the head' +
+                    ' — nothing to heal this tick');
+        return { active: false, runs: 0, healed: 0 };
+    }
+    var healed = 0;
+    runs.forEach(function (r) {
+        if (DRY) {
+            console.log('  🧪 [dry] rerun skipped: run ' + r.id +
+                        ' (' + (r.path || r.name) + ', ' + r.conclusion + ')');
+            return;
+        }
+        try {
+            cli_execute_command({
+                command: 'gh api -X POST repos/' + repoInfo.owner + '/' +
+                         repoInfo.repo + '/actions/runs/' + r.id + '/rerun'
+            });
+            healed++;
+            console.log('  🔁 ' + key + ' re-ran cancelled run ' + r.id +
+                        ' (' + (r.path || r.name) + ') on head ' +
+                        String(headSha).slice(0, 7) + ' — required contexts re-stamp');
